bad AS (
  SELECT g.id, 'i' AS col, g.c0 AS got, w.c0 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c0 IS NOT NULL AND g.c0 IS DISTINCT FROM w.c0
  UNION ALL
  SELECT g.id, 'd' AS col, g.c1 AS got, w.c1 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c1 IS NOT NULL AND g.c1 IS DISTINCT FROM w.c1
  UNION ALL
  SELECT g.id, 'd0' AS col, g.c2 AS got, w.c2 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c2 IS NOT NULL AND g.c2 IS DISTINCT FROM w.c2
  UNION ALL
  SELECT g.id, 'f' AS col, g.c3 AS got, w.c3 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c3 IS NOT NULL AND g.c3 IS DISTINCT FROM w.c3
  UNION ALL
  SELECT g.id, 'f_abs' AS col, g.c4 AS got, w.c4 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c4 IS NOT NULL AND g.c4 IS DISTINCT FROM w.c4
  UNION ALL
  SELECT g.id, 'f_rel' AS col, g.c5 AS got, w.c5 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c5 IS NOT NULL AND g.c5 IS DISTINCT FROM w.c5
  UNION ALL
  SELECT g.id, 'b' AS col, g.c6 AS got, w.c6 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c6 IS NOT NULL AND g.c6 IS DISTINCT FROM w.c6
  UNION ALL
  SELECT g.id, 'dt' AS col, g.c7 AS got, w.c7 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c7 IS NOT NULL AND g.c7 IS DISTINCT FROM w.c7
  UNION ALL
  SELECT g.id, 'ts' AS col, g.c8 AS got, w.c8 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c8 IS NOT NULL AND g.c8 IS DISTINCT FROM w.c8
  UNION ALL
  SELECT g.id, 'tstz' AS col, g.c9 AS got, w.c9 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c9 IS NOT NULL AND g.c9 IS DISTINCT FROM w.c9
  UNION ALL
  SELECT g.id, 's' AS col, g.c10 AS got, w.c10 AS want FROM got g JOIN want w ON g.id = w.id WHERE w.c10 IS NOT NULL AND g.c10 IS DISTINCT FROM w.c10
  UNION ALL
  SELECT g.id, 'row_text' AS col, g.row_text AS got, w.row_text AS want FROM got g JOIN want w ON g.id = w.id WHERE w.row_text IS NOT NULL AND g.row_text IS DISTINCT FROM w.row_text
  UNION ALL
  SELECT g.id, 'row_hash' AS col, g.row_hash AS got, w.row_hash AS want FROM got g JOIN want w ON g.id = w.id WHERE w.row_hash IS NOT NULL AND g.row_hash IS DISTINCT FROM w.row_hash
)
SELECT 'mismatch' AS result, id, col, got, want FROM bad
UNION ALL
SELECT 'pass', count(*), 'all columns', CAST(NULL AS STRING), CAST(NULL AS STRING) FROM got
HAVING (SELECT count(*) FROM bad) = 0 AND count(*) = 400
ORDER BY id;
